<template><view class="page"><view class="card"><input v-model="title" placeholder="提醒内容"/><input v-model="time" placeholder="例如 21:00"/><button class="primary" @click="create">创建</button></view><view v-for="item in items" :key="item.reminder_id" class="card">{{item.title}} · {{item.schedule_rule?.time}} · {{item.status}}</view></view></template>
<script setup>import{ref,onMounted}from'vue';import{api}from'../../api';const title=ref('测血糖'),time=ref('21:00'),items=ref([]);async function load(){items.value=await api.reminders()}async function create(){await api.createReminder({title:title.value,schedule_rule:{time:time.value},timezone:'Asia/Shanghai',channel:'in_app'});await load()}onMounted(load)</script>
